mapper.select:
select id, user_id, user_name, module, content, url, method, param, result, fail_reason, update_time, create_time from t_user_operate_log
AND DATE_FORMAT(create_time, '%Y-%m-%d') >= #{queryDTO.startDate}
AND DATE_FORMAT(create_time, '%Y-%m-%d') <= #{queryDTO.endDate}
AND INSTR(user_name,#{queryDTO.userName})
AND result = #{queryDTO.resultFlag}
order by create_time desc

SELECT type accessTerminal, DATE(create_time) date, count(DISTINCT id) count FROM up_statistics_pv where model like '%首页%'
AND type = #{query.nUserLoginType}
AND create_time >= #{query.nUserLoginStartDate} AND create_time <= #{query.nUserLoginEndDate}
GROUP BY date,accessTerminal

SELECT access_terminal type, DATE_FORMAT(create_time, '%m-%d') date, count(DISTINCT user_id) count FROM t_user_login_log where login_status = 1 and login_type = 1
AND access_terminal = #{query.userLoginPlateType}
and create_time >= DATE_SUB(CURDATE(), INTERVAL 14 DAY) AND create_time <= CONCAT(CURDATE(), ' 23:59:59')
AND DATE(create_time) between #{query.userLoginStartDate} AND #{query.userLoginEndDate}
GROUP BY DATE(create_time),access_terminal
